import { render, screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it } from 'vitest'
import { IssueListPage } from '../pages/IssueListPage'
import { installFakeApi, makeIssue } from './fakeApi'

async function addIssue(title: string, description = 'A description', steps = 'Some steps') {
  await userEvent.type(screen.getByLabelText('Title'), title)
  await userEvent.type(screen.getByLabelText('Description'), description)
  await userEvent.type(screen.getByLabelText('Steps to reproduce'), steps)
  await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
}

function cardFor(title: string): HTMLElement {
  return screen.getByRole('heading', { name: title }).closest('article') as HTMLElement
}

describe('IssueListPage (changing data)', () => {
  it('adds an issue: sends it to the API and shows it without a page reload', async () => {
    const { seen } = installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')

    await addIssue('Dark mode flickers')

    expect(await screen.findByRole('heading', { name: 'Dark mode flickers' })).toBeInTheDocument()
    expect(screen.getByText('Showing 5 of 5 issues')).toBeInTheDocument()
    const post = seen.find((r) => r.method === 'POST')
    expect(post?.url).toBe('/issues')
    expect(post?.body).toMatchObject({ title: 'Dark mode flickers', priority: 'medium' })
  })

  it('clears the form after a good add', async () => {
    installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')
    await addIssue('Dark mode flickers')
    await screen.findByRole('heading', { name: 'Dark mode flickers' })
    expect(screen.getByLabelText('Title')).toHaveValue('')
  })

  it('does not call the API when the form is not valid', async () => {
    const { seen } = installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')
    await userEvent.click(screen.getByRole('button', { name: 'Add issue' }))
    expect(screen.getAllByRole('alert').length).toBeGreaterThan(0)
    expect(seen.filter((r) => r.method === 'POST')).toHaveLength(0)
  })

  it('shows the server message and adds nothing when the API refuses', async () => {
    installFakeApi(undefined, { failures: { 'POST /issues': 403 } })
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')

    await addIssue('Dark mode flickers')

    expect(await screen.findByText('Your role may not do that')).toBeInTheDocument()
    expect(screen.getByText('Showing 4 of 4 issues')).toBeInTheDocument()
    expect(screen.getByLabelText('Title')).toHaveValue('Dark mode flickers')
  })

  it('can add the first issue to an empty list', async () => {
    installFakeApi([])
    render(<IssueListPage />)
    await screen.findByText(/no issues yet/i)

    await addIssue('My very first issue')

    expect(await screen.findByRole('heading', { name: 'My very first issue' })).toBeInTheDocument()
    expect(screen.queryByText(/no issues yet/i)).not.toBeInTheDocument()
  })

  it('changes a status: sends PATCH /issues/:id/status and shows the new status', async () => {
    const { seen } = installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')

    const card = cardFor('Login button does nothing')
    await userEvent.selectOptions(within(card).getByLabelText('Status'), 'closed')

    await screen.findByText('Showing 4 of 4 issues')
    const patch = seen.find((r) => r.method === 'PATCH')
    expect(patch?.url).toBe('/issues/000000000000000000000001/status')
    expect(patch?.body).toEqual({ status: 'closed' })
    expect(within(cardFor('Login button does nothing')).getByLabelText('Status')).toHaveValue('closed')
  })

  it('deletes an issue after the person confirms', async () => {
    const { seen } = installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')

    const card = cardFor('Typo on the home page')
    await userEvent.click(within(card).getByRole('button', { name: 'Delete' }))
    await userEvent.click(within(card).getByRole('button', { name: 'Yes, delete' }))

    expect(await screen.findByText('Showing 3 of 3 issues')).toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: 'Typo on the home page' })).not.toBeInTheDocument()
    expect(seen.find((r) => r.method === 'DELETE')?.url).toBe('/issues/000000000000000000000002')
  })

  it('does not delete anything when the person cancels', async () => {
    const { seen } = installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')

    const card = cardFor('Typo on the home page')
    await userEvent.click(within(card).getByRole('button', { name: 'Delete' }))
    await userEvent.click(within(card).getByRole('button', { name: 'Cancel' }))

    expect(seen.filter((r) => r.method === 'DELETE')).toHaveLength(0)
    expect(screen.getByText('Showing 4 of 4 issues')).toBeInTheDocument()
  })

  it('keeps the issue and shows an alert when the API refuses a delete', async () => {
    installFakeApi([makeIssue(1, { title: 'Keep me' })], {
      failures: { 'DELETE /issues/000000000000000000000001': 403 },
    })
    render(<IssueListPage />)
    await screen.findByText('Showing 1 of 1 issues')

    const card = cardFor('Keep me')
    await userEvent.click(within(card).getByRole('button', { name: 'Delete' }))
    await userEvent.click(within(card).getByRole('button', { name: 'Yes, delete' }))

    expect(await screen.findByRole('alert')).toHaveTextContent('Your role may not do that')
    expect(screen.getByRole('heading', { name: 'Keep me' })).toBeInTheDocument()
  })
})
